SELECT s.show_id AS showId, s.movie_id AS movieId, s.cinema_id AS cinemaId, s.hall_id AS hallId, s.seat_map_id AS seatMapId, s.start_time AS startTime, s.end_time AS endTime, s.price, s.status, s.created_at AS createdAt, s.updated_at AS updatedAt, h.name AS hallName, m.title AS movieTitle FROM show_schedule s LEFT JOIN hall h ON h.hall_id = s.hall_id LEFT JOIN movie m ON m.movie_id = s.movie_id WHERE s.cinema_id = #{cinemaId} AND s.status IN ('on_sale', 'cancelled')
AND s.movie_id = #{movieId}
AND s.start_time >= #{after}
ORDER BY s.start_time ASC

SELECT s.show_id AS showId, s.movie_id AS movieId, s.cinema_id AS cinemaId, s.hall_id AS hallId, s.seat_map_id AS seatMapId, s.start_time AS startTime, s.end_time AS endTime, s.price, s.status, s.created_at AS createdAt, s.updated_at AS updatedAt, h.name AS hallName, m.title AS movieTitle FROM show_schedule s LEFT JOIN hall h ON h.hall_id = s.hall_id LEFT JOIN movie m ON m.movie_id = s.movie_id WHERE s.cinema_id = #{cinemaId} AND s.status IN ('on_sale', 'cancelled')
AND s.movie_id = #{movieId}
AND s.start_time >= #{after}
ORDER BY s.start_time ASC

SELECT show_id AS showId, hall_id AS hallId,
       start_time AS startTime, end_time AS endTime, status
FROM show_schedule
WHERE hall_id = #{hallId}
  AND status <> 'cancelled'

      AND show_id <> #{excludeShowId}

  AND start_time < (#{endTime} + INTERVAL '20 minutes')
  AND (end_time + INTERVAL '20 minutes') > #{startTime}

SELECT show_id AS showId, hall_id AS hallId,
       start_time AS startTime, end_time AS endTime, status
FROM show_schedule
WHERE hall_id = #{hallId}
  AND status <> 'cancelled'

      AND show_id <> #{excludeShowId}

  AND start_time < DATEADD('MINUTE', 20, #{endTime})
  AND DATEADD('MINUTE', 20, end_time) > #{startTime}

SELECT COUNT(1) FROM show_schedule
WHERE movie_id = #{movieId}
  AND status = 'on_sale'
  AND start_time > #{now}


SELECT s.movie_id AS movieId, MIN(s.start_time) AS startTime
FROM show_schedule s
WHERE s.start_time >= #{startTime}
  AND s.start_time < #{endTime}
  AND s.status = 'on_sale'


    AND s.cinema_id = #{cinemaId}

GROUP BY s.movie_id
ORDER BY MIN(s.start_time) ASC
LIMIT #{limit} OFFSET #{offset}


SELECT COUNT(DISTINCT s.movie_id)
FROM show_schedule s
WHERE s.start_time >= #{startTime}
  AND s.start_time < #{endTime}
  AND s.status = 'on_sale'


    AND s.cinema_id = #{cinemaId}
